1	// CsrTrigger pre-scans an instruction buffer (typically the loadable
2	// executable segments of an ELF) for `csrw 0x7C0, *` instructions and
3	// records their PCs. At retire time the simulator queries lookup(pc) to
4	// decide whether to drain state and hand back to QEMU.
5	//
6	// Pure logic: no SystemC, no DMI bus. Decoupled from GPR access -- the
7	// caller resolves runtime-kind rs1 values via decode_csrrw_rs1.
8	
9	#pragma once
10	
11	#include "hybrid/insn_match.h"
12	
13	#include <algorithm>
14	#include <cstddef>
15	#include <cstdint>
16	#include <cstring>
17	#include <optional>
18	#include <span>
19	#include <unordered_map>
20	#include <vector>
21	
22	namespace hybrid
23	{
24	
25	struct CsrTriggerHit
26	{
27	  hybrid_handoff_kind kind;
28	  uint32_t insn;
29	};
30	
31	inline auto decode_csrrw_rs1(uint32_t insn) -> uint8_t
32	{
33	  return static_cast<uint8_t>((insn >> 15) & 0x1Fu);
34	}
35	
36	class CsrTrigger
37	{
38	public:
39	  void scan_buffer(std::span<const uint8_t> code, uint64_t base_pc)
40	  {
41	    std::size_t i = 0;
42	    while (i + sizeof(uint16_t) <= code.size()) {
43	      uint16_t lo = 0;
44	      std::memcpy(&lo, code.data() + i, sizeof(lo));
45	
46	      const bool is_32 = (lo & 0x3u) == 0x3u;
47	      if (is_32) {
48	        if (i + sizeof(uint32_t) > code.size()) break;
49	        uint32_t insn = 0;
50	        std::memcpy(&insn, code.data() + i, sizeof(insn));
51	        hybrid_handoff_kind kind = HYBRID_HANDOFF_NONE;
52	        if (hybrid_match_handoff_insn(insn, &kind)) {
53	          hits_.insert_or_assign(base_pc + i, CsrTriggerHit{kind, insn});
54	        }
55	        i += sizeof(uint32_t);
56	      } else {
57	        i += sizeof(uint16_t);
58	      }
59	    }
60	  }
61	
62	  // PC-trigger mode: insert a synthetic hit without scanning. Used when the
63	  // orchestrator passes --hybrid-exit-pc on the CLI; in that case the binary
64	  // need not contain a magic csrwi, and `insn` is unused (HandoffController
65	  // decodes the insn only on the RUNTIME arm; PC mode only inserts EXIT).
66	  void add_pc_hit(uint64_t pc, hybrid_handoff_kind kind)
67	  {
68	    hits_.insert_or_assign(pc, CsrTriggerHit{kind, /*insn=*/0u});
69	  }
70	
71	  auto lookup(uint64_t pc) const -> std::optional<CsrTriggerHit>
72	  {
73	    if (auto it = hits_.find(pc); it != hits_.end()) return it->second;
74	    return std::nullopt;
75	  }
76	
77	  auto empty() const -> bool { return hits_.empty(); }
78	
79	  // Collect every recorded PC whose hit matches `kind`. The result is sorted
80	  // ascending so callers (e.g. the ROI kanata-gate derivation) get a stable
81	  // order regardless of hash-map iteration order.
82	  auto pcs_of_kind(hybrid_handoff_kind kind) const -> std::vector<uint64_t>
83	  {
84	    std::vector<uint64_t> pcs;
85	    pcs.reserve(hits_.size());
86	    for (const auto& [pc, hit]: hits_)
87	      if (hit.kind == kind) pcs.push_back(pc);
88	    std::sort(pcs.begin(), pcs.end());
89	    return pcs;
90	  }
91	
92	private:
93	  std::unordered_map<uint64_t, CsrTriggerHit> hits_;
94	};
95	
96	}  // namespace hybrid
