1	// MeasureStartSnapshot - F14 observer that captures (mcycle, minstret)
2	// K vsim-retires after entry. Used by the gem5-style warmup window: the
3	// vsim phase still runs N cold-cache cycles, but the reported ROI delta is
4	// taken from the K-th commit instead of from vsim entry, so the cold prefix
5	// is excluded from the measurement.
6	//
7	// Duck-types the observer surface the HandoffController invokes via
8	// if-constexpr: `observe_commit() -> void`. Accessors expose the captured
9	// values for F16 (StateDrain) to copy into the ABI struct.
10	//
11	// K = 0 disables the observer: no DMI traffic, snapshot fields stay zero.
12	// This is the wire-format K=0 contract from F13: a zero mcycle_at_measure_start
13	// downstream means "warmup not enabled / not reached".
14	//
15	// Capture sequence on the K-th retire: halt the hart via DMCONTROL,
16	// abstract-read mcycle and minstret, then issue resumereq so the workload
17	// continues. Each halt-read-resume cycle is one-shot per run; the flag
18	// `reached_` guards against re-capture.
19	
20	#pragma once
21	
22	#include "hybrid/abstract_command.hpp"
23	#include "hybrid/dmi_poll.hpp"
24	#include "hybrid/resume_driver.hpp"
25	
26	#include <cstdint>
27	
28	namespace hybrid
29	{
30	
31	class MeasureStartSnapshot
32	{
33	public:
34	  using RD = ResumeDriver;
35	
36	  MeasureStartSnapshot(uint64_t k, DmiBus& bus)
37	      : k_{k}, bus_{&bus}
38	  {}
39	
40	  // Move construction transfers state and bus pointer.
41	  MeasureStartSnapshot(MeasureStartSnapshot&&) noexcept            = default;
42	  MeasureStartSnapshot& operator=(MeasureStartSnapshot&&) noexcept = default;
43	
44	  void observe_commit()
45	  {
46	    if (k_ == 0 || reached_) return;
47	    ++retired_;
48	    if (retired_ != k_) return;
49	    capture();
50	    reached_ = true;
51	  }
52	
53	  auto snapshot_reached() const -> bool { return reached_; }
54	  auto mcycle_at_measure_start() const -> uint64_t { return mcycle_; }
55	  auto minstret_at_measure_start() const -> uint64_t { return minstret_; }
56	  auto target() const -> uint64_t { return k_; }
57	
58	private:
59	  void capture()
60	  {
61	    // Halt the hart so abstract-command CSR reads are accepted.
62	    bus_->write(RD::kDmcontrol, RD::kDmcontrolDmactive);
63	    bus_->write(RD::kDmcontrol, RD::kDmcontrolDmactive | RD::kDmcontrolHaltreq);
64	    poll_until_set(*bus_, RD::kDmstatus, RD::kDmstatusAllhalted,
65	                   "MeasureStartSnapshot halt");
66	
67	    mcycle_   = read_register_64(*bus_, regno_csr(RD::kCsrMcycle),
68	                                 "MeasureStartSnapshot mcycle");
69	    minstret_ = read_register_64(*bus_, regno_csr(RD::kCsrMinstret),
70	                                 "MeasureStartSnapshot minstret");
71	
72	    // Resume so the warmup window continues into the measured region.
73	    // The hart re-acks via DmstatusAllresumeack, but we do not block here:
74	    // the simulator's run loop drives the next sc_start, which lets the
75	    // hart's running state propagate naturally.
76	    bus_->write(RD::kDmcontrol, RD::kDmcontrolDmactive | RD::kDmcontrolResumereq);
77	    bus_->write(RD::kDmcontrol, RD::kDmcontrolDmactive);  // clear resumereq
78	  }
79	
80	  uint64_t k_;
81	  DmiBus*  bus_;
82	  uint64_t retired_ = 0;
83	  bool     reached_ = false;
84	  uint64_t mcycle_  = 0;
85	  uint64_t minstret_ = 0;
86	};
87	
88	// NullObserver: default Observer for HandoffController instantiations that
89	// do not opt into the warmup snapshot. Empty type; HandoffController gates
90	// the observer hook through if-constexpr `requires { obs.observe_commit(); }`,
91	// which NullObserver omits, so the call is compiled out.
92	struct NullObserver
93	{};
