1	// Hybrid ROI single-shot kanata window. csr-mode requires a unique exit
2	// csrwi 0x7C0,1 so the recorded window is reproducible across runs; the
3	// 0/>1 throws push the user to pc-mode where they pick the exit explicitly.
4	
5	#pragma once
6	
7	#include "hybrid/csr_trigger.hpp"
8	#include "hybrid/insn_match.h"
9	#include "pipeview/kanata_logger.hpp"
10	
11	#include <cstdint>
12	#include <optional>
