18	
19	inline auto derive_roi_kanata_gate(
20	  const CsrTrigger& trigger, uint64_t resume_pc,
21	  std::optional<uint64_t> explicit_exit_pc) -> kanata::LoopGate
22	{
23	  uint64_t end_pc = 0;
24	  if (explicit_exit_pc) {
25	    end_pc = *explicit_exit_pc;
26	  } else {
27	    const auto exits = trigger.pcs_of_kind(HYBRID_HANDOFF_EXIT);
28	    if (exits.empty()) {
29	      throw std::runtime_error(
30	        "--kanata-roi: no csrwi 0x7C0,1 (EXIT) marker found in ELF -- "
31	        "use --mode pc with --pc-end");
32	    }
33	    if (exits.size() > 1) {
34	      throw std::runtime_error(
35	        "--kanata-roi: " + std::to_string(exits.size())
36	        + " csrwi 0x7C0,1 (EXIT) markers in ELF -- "
37	          "use --mode pc with an explicit --pc-end to disambiguate");
38	    }
39	    end_pc = exits.front();
40	  }
41	  return kanata::LoopGate{resume_pc, end_pc, /*skip=*/0u, /*record=*/1u};
42	}
